import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom date range parser - supports ISO 8601 and relative dates
    private String parseDateExpression(String input) {
        if (input == null) return "CURRENT_DATE";
        // Allow relative expressions like 'now-7d', 'now-30d'
        Pattern rel = Pattern.compile("^now-([0-9]+)d$");
        Matcher m = rel.matcher(input.trim());
        if (m.matches()) {
            return "CURRENT_DATE - INTERVAL '" + m.group(1) + " days'";
        }
        // Otherwise treat as literal date expression for flexibility
        return input;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String groupBy = req.getParameter("group");

        // Validate report type against allowlist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate groupBy against allowlist
        String[] validGroups = {"day", "week", "month", "quarter"};
        String safeGroup = "day";
        for (String g : validGroups) {
            if (g.equals(groupBy)) { safeGroup = g; break; }
        }

        String startExpr = parseDateExpression(startDate);
        String endExpr = parseDateExpression(endDate);

        String sql = "SELECT date_trunc('" + safeGroup + "', created_at) as period, "
                   + "COUNT(*) as total, SUM(amount) as revenue "
                   + "FROM transactions "
                   + "WHERE created_at >= " + startExpr
                   + " AND created_at <= " + endExpr
                   + " AND report_category = ?"
                   + " GROUP BY period ORDER BY period";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, reportType);
            ResultSet rs = ps.executeQuery();

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("period", rs.getString("period"));
                row.put("total", rs.getInt("total"));
                row.put("revenue", rs.getDouble("revenue"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private boolean isValidReportType(String type) {
        String[] valid = {"sales", "refunds", "subscriptions", "trials"};
        for (String v : valid) {
            if (v.equals(type)) return true;
        }
        return false;
    }

    // Health check endpoint used by load balancer
    @Override
    protected void doHead(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setStatus(200);
    }
}
